	public Set referencedPages()
    {
        SetEnumerator	parmMethods;
        MapEnumerator	menuItems;
        SysDictMethod	methods;
        TFMPageID		pageId;

        if (referencedPages != null)
        {
            return referencedPages;
        }
        referencedPages = new Set(Types::String);
        parmMethods = TFMFormLookupHelper::parmMethodsOnClass(classIdGet(configuration),false,Types::Class).getEnumerator();

        SysDictClass configurationSysDictClass = new SysDictClass(classIdGet(configuration));

		while (parmMethods.moveNext())
        {
            methods = parmMethods.current();
            if( methods.returnTypeName() == extendedTypeStr(TFMPageID))
            {
                pageId = configurationSysDictClass.callObject(methods.name(),configuration);
                referencedPages.add(pageId);
            }
        }
        menuItems = TFMPageMenuItemsFormHelper::getPageMenuItemStateConfigurations(name).getEnumerator();
		while (menuItems.moveNext())
        {
            referencedPages.add(menuItems.currentKey());
        }
        return referencedPages;
    }

