public str parmId(str _name = name)
{
    if (configuration &&  _name != name)
    {
        name = _name;
        configuration.parmName(name);
        if(!configuration.parmType())
        {
            configuration.parmType(name);
        }
    }

    name = _name;

    return name;
}

