public str parmTitle(str _title = title)
{
    title = _title;

    // legacy handling of titles
    if (!strScan(title,' ',1,1000) && subStr(title,1,4) == 'Page' && subStr(title,strLen(title)-4,5) == 'Title')
    {
        return '@{'+title+'}';
    }

    return title;
}

    public void new()
    {
        SysDictClass DC = new SysDictClass(classIdGet(this));
        TFMPageTypeAttribute  pageTypeAttr = DC.getAttribute(classStr(TFMPageTypeAttribute));

        if (pageTypeAttr)
        {
            type = pageTypeAttr.parmPageType();

            this.initFromType();
        }
        tileEntries = new Map(Types::String, Types::String);
        tileForms = new Map(Types::String, Types::String);
        description = strFmt("@TFM:Thisisa1page",type);
        referencedPages = null;
        numberOfPromotedItems = 3;
        dsBlocks = new Set(Types::Class);
	}

