public TFMMenuItemStateConfiguration addAction(TFMPageID _pageName, int _promoted = -1, int _promoteOffset = 0)
{
    TFMMenuItemStateConfiguration conf;
    if (actions == null)
    {
        actions = this.DefaultActions(_promoteOffset);
    }
    conf = TFMMenuItemStateConfiguration::Construct(_pageName,_promoted);
    actions.insert(conf.parmMenuItemName(),conf);
    return conf;
}

public void addActionClass(TFMMenuItemStateConfiguration _menuItemStateConf,int _promoteOffset = 0)
{
    if (actions == null)
    {
        actions = this.DefaultActions(_promoteOffset);
    }
    actions.insert(_menuItemStateConf.parmMenuItemName(),_menuItemStateConf);
}

public TFMMenuItemStateConfiguration addAdhocAction(MethodName _methodName, int _promoted = -1, int _promoteOffset = 0, TFMPageID _navigateToOnSuccesfulPost = '')
{
    TFMMenuItemStateConfiguration				conf;
    TFMPageLineAdhocRequestAttribute			adhocAttribute = new TFMPageLineAdhocRequestAttribute(_methodName,'','',true);
    TFMPageActionAttribute						pageAction;
    TFMPageAdhocMenuItemsAdditionalProperties	additionalProps;
    TFMDocumentHandler							handler = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(TFMDocumentHandler), adhocAttribute);
    SysDictClass								sdc;
    Array										clsAttributes;
    int											i;
    SysDictMethod								sdm;
    TFMDocumenttypeAttribute					docTypeAttr;
    if (actions == null)
    {
        actions = this.DefaultActions(_promoteOffset);
    }
    sdc = new SysDictClass(classIdGet(handler));
    clsAttributes = sdc.getAttributes(classStr(TFMPageLineAdhocRequestAttribute));
    if (0 == clsAttributes.lastIndex())
    {
        return null;
    }
    for (i = 1; i <= clsAttributes.lastIndex(); i++)
    {
        adhocAttribute = clsAttributes.value(i);
        if (adhocAttribute.parmMethodName() == _methodName)
        {
            pageAction = new TFMPageActionAttribute(TFMPageMenuItemTypes::AdhocAction,adhocAttribute.parmIcon(),_promoted > -1,false);
            //Find Post Adhoc Document
            sdm = new SysDictMethod(UtilElementType::ClassInstanceMethod,sdc.id(), _methodName);
            docTypeAttr = sdm.getAttribute(ClassStr(TFMDocumenttypeAttribute));
            if(docTypeAttr)
            {
                additionalProps = new TFMPageAdhocMenuItemsAdditionalProperties();
                additionalProps.parmDocumentType(docTypeAttr.parmDocumentType());
                additionalProps.parmContentType(docTypeAttr.parmContentType());
                additionalProps.parmRefreshOnSuccess(adhocAttribute.parmRefreshOnSuccess());
                additionalProps.parmNavigateTo(_navigateToOnSuccesfulPost);
            }
            conf = TFMMenuItemStateConfiguration::Construct(adhocAttribute.parmMethodName(), _promoted, pageAction);
            conf.parmAdditionalProperties(additionalProps);
            conf.parmTitle(adhocAttribute.parmTitle());
        }
    }

    actions.insert(conf.parmMenuItemName(),conf);
    return conf;
}

    public Map DefaultActions(int _promoteOffset = 0)
    {
        Map								defaultActionsMap = new Map(Types::String, Types::Class);
        TFMMenuItemStateConfiguration	menuItemStateConf;
        boolean							enabled = true;
        TFMListId						listId = this.getListId();

		if (!listId)
        {
			//Not a page showing data, and should not have any menu items per default
            return defaultActionsMap;
        }

        if (_promoteOffset == -5)
        {
            enabled = false;
        }

        menuItemStateConf = TFMMenuItemStateConfiguration::Construct('RegisterImage', 1 + _promoteOffset);
        menuItemStateConf.parmEnabled(enabled);
        if (name != menuItemStateConf.parmMenuItemName())
        {
        defaultActionsMap.insert(menuItemStateConf.parmMenuItemName(),menuItemStateConf);
        }

        menuItemStateConf = TFMMenuItemStateConfiguration::Construct('attachments', 2 + _promoteOffset);
        menuItemStateConf.parmEnabled(enabled);
        if (name != menuItemStateConf.parmMenuItemName())
        {
			//No Self-reference
			defaultActionsMap.insert(menuItemStateConf.parmMenuItemName(),menuItemStateConf);
        }

        menuItemStateConf = TFMMenuItemStateConfiguration::Construct(TFMConstants::MenuItemTypeBarcode(), -1, new TFMPageActionAttribute(TFMPageMenuItemTypes::PageMenuItem));
        menuItemStateConf.parmEnabled(enabled);
        menuItemStateConf.getPageActionSetup().parmVisibleWhenNoData(true);
        defaultActionsMap.insert(menuItemStateConf.parmMenuItemName(),menuItemStateConf);

        return TFMHelper::mergeMaps(defaultActionsMap,actions == null ? new Map(Types::String, Types::Class) : actions);
    }

