public void initFromType()
{
    configuration = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(TFMPageConfiguration), new TFMPageTypeAttribute(type,''));
    if (configuration)
    {
        configuration.parmName(name);
        if(!configuration.parmType())
        {
            configuration.parmType(name);
        }
    }
}

