public static TFMPage getPageClass(TFMPageType _pageType, str _name)
{
    TFMPageTypeAttribute pageType = new TFMPageTypeAttribute(_pageType,'');
    TFMPage pageClass = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(TFMPage), pageType);
    if (pageClass)
    {
        pageClass.parmId(_name);
        pageClass.parmType(_pageType);
    }
    return pageClass;
}

