public XMLDocument getXML(TFMPages _pages)
{
    //XML resultXML;
    XmlDocument xmlDoc = XmlDocument::newBlank();
    XmlElement  pageElement = xmlDoc.createElement('page');
    XmlElement	titlePage = xmlDoc.createElement('title');
    XmlElement	typeBarcodeElement = xmlDoc.createElement(TFMConstants::MenuItemTypeBarcode());
    XmlElement  actionNode;
    XmlElement  menuElement;
    TFMPageMenuItems typeBarcodeMenuItemRow;
    TFMPage::addMethodsAsAttributes(this, pageElement);
    Map groups;


    titlePage.setAttribute('defaultValue', TFMTranslationProvider::getTranslation(this.parmTitle()));

    pageElement.appendChild(titlePage);

    if(configuration)
    {
        configuration.parmFilter(filterName);
        groups = configuration.appendToXML(pageElement, this);
    }


    typeBarcodeMenuItemRow = TFMPageMenuItems::find(this.parmId(), TFMConstants::MenuItemTypeBarcode());

    // add typeBarcode element
    typeBarcodeElement.setAttribute('enabled', (!typeBarcodeMenuItemRow || typeBarcodeMenuItemRow.Hide) ? 'false' : 'OnEmptyListUtilizingDataMember');
    typeBarcodeElement.setAttribute('dataMember',TFMConstants::MenuItemTypeBarcode());

    TFMGS1AITypeBarcodeSetup::modifyOutput(typeBarcodeElement,name);
    pageElement.appendChild(typeBarcodeElement);

    if(configuration) // TODO: Put this in, to prevent errors, but we should investigate if it's normal that pages don't always have configuration element.
    {
        actionNode = TFMPageMenuItemsHelper::addMenuItemsToXML(this, _pages, pageElement, configuration.GetConfigurationPageName());
        pageElement.appendChild(actionNode);   
    }

    // Update number of promoted menu items
    menuElement = pageElement.getNamedElement('menu');
    if(menuElement)
    {
        menuElement.setAttribute('numberOfPromotedItems', int2Str(TFMPageMenuItemsHelper::getNumberOfPromotedItems(this)));
    }

    xmlDoc.appendChild(pageElement);

    return xmlDoc;
}

public static void addMethodsAsAttributes(Object _class, XmlElement _xmlElement)
{
    DictClass					dc = new DictClass(classIdGet(_class));
    XmlElement					subNode;
    Map							subNodes = new Map(Types::String, Types::Class);
    MapEnumerator				methods = TFMAttributeHandler::getMethodNamesFromSysAttribute(classIdGet(_class),new TFMPageAttributeAttribute(''),true).getEnumerator();
    TFMPageAttributeAttribute	pageAttr;

    while (methods.moveNext())
    {
        pageAttr = methods.currentValue();
        if (pageAttr.parmXPath())
        {
            subNode = subNodes.exists(pageAttr.parmXPath()) ? subNodes.lookup(pageAttr.parmXPath()) : _xmlElement.ownerDocument().createElement(pageAttr.parmXPath());
            if (!subNodes.exists(pageAttr.parmXPath()))
            {
                subNodes.insert(pageAttr.parmXPath(),subNode);
                _xmlElement.appendChild(subNode);
            }
        }
        else
        {
            subNode = _xmlElement;
        }
        subNode.setAttribute((pageAttr.parmName() ? pageAttr.parmName() : TFMRegistrationCollector::smallBeginnings(subStr(methods.currentKey(),5,strLen(methods.currentKey())))),dc.callObject(methods.currentKey(),_class));
    }
}

	public TFMListId getListId()
