    public void setListId(TFMListId _listId, boolean _writeAsDelta = false)
    {
        Object		config = this.getConfiguration();
        if (SysTest::hasMethod(config, methodStr(TFMPageOrderLinesConfiguration,parmListId )))
        {
            config.parmListId(_listId);
			if (_writeAsDelta)
            {
                TFMPageConfigParms::CreateOrUpdateParameter(this.parmId(),classId2Name(classIdGet(config)),methodStr(TFMPageOrderLinesConfiguration,parmListId ),_listId);
            }
		}
    }

	public str descriptionHtml(boolean _onlyTop = true)
    {        
        str					html = '<table height="100%"><tr><td width="85"><img src="'+TFMDocGetMedia::getURLFromIconName(this.parmIcon())+'" width="60px" height="60px"/></td><td colspan="4" width="425px"><h1>' + this.parmId() + '</h1><h3>'+ TFMHelper::convertCamelCaseToNiceText(this.parmType())+ '</h3><h4>'+ description +'</h4></td></tr>';//</table><hr>';
        MapEnumerator		mEnum;
        str					imgUrl;
        str					icon;
        str					descriptionType;
        int					i=1;
        this.addPageTiles();

        mEnum = tileEntries.getEnumerator();
        while (mEnum.moveNext() && !_onlyTop)
        {
            icon = subStr(mEnum.currentValue(),1,strScan(mEnum.currentValue(),'|',1,100)-1);
            imgUrl = TFMDocGetMedia::getURLFromIconName(strReplace(icon,'|',''));
            descriptionType = subStr(mEnum.currentValue(),strScan(mEnum.currentValue(),'|',1,100)+1,1000);
            if (i mod 2)
            {
				//even
				html += '<tr>';
            }	
			else
            {
				//odd
                html += '<td>&nbsp;&nbsp;&nbsp;</td>';
            }
            html += '<td colspan="2"><br><div style="background-color: #EEEEEE; padding: 10px;border-bottom-style: groove;width: 255px;box-shadow: 0 4px 8px 0 rgba(0, 0, 0, 0.2), 0 6px 20px 0 rgba(0, 0, 0, 0.19);text-align: left;"><table><tr><td width="55px"><img src="'+imgUrl+'" width="45px" height="45px"/></td><td><h4><b><u>'+mEnum.currentKey()+'</u></b></h4><h3>'+descriptionType+'</h3></td></tr></table></div></td>';
			if (!(i mod 2))
            {
				//odd
                html += '</tr>';
            }
            i++;
        }

        return html + '</table>';
    }

public Map tilesImages()
{
    Map images = new Map(Types::String, Types::String);
    MapEnumerator		mEnum;
    str                 tileTitle;
    str					icon;
    str					descriptionType;
    this.addPageTiles();

    mEnum = tileEntries.getEnumerator();
    while (mEnum.moveNext())
    {
        icon = subStr(mEnum.currentValue(),1,strScan(mEnum.currentValue(),'|',1,100)-1);
        icon = strReplace(icon,'|','');
        tileTitle = mEnum.currentKey();
        descriptionType = TFMPage::StripHTML(subStr(mEnum.currentValue(),strScan(mEnum.currentValue(),'|',1,100)+1,1000));

        images.insert(mEnum.currentKey(),TFMHtmlHelper::entityTileHtml(icon,tileTitle,descriptionType));
    }

    return images;
}

public str tileKey2FormName(str _key)
{
    return tileForms.exists(_key) ? tileForms.lookup(_key) : '';
}

public static System.String StripHTML(System.String _input)
{
    System.String patter = '<.*?>';
    System.String empty = ''; 
    System.String res;

    res =System.Text.RegularExpressions.Regex::Replace(_input, patter, empty);

    return res;
}

protected void addPageTiles()
{
    TFMListId			listId = this.getListId();
    TFMPageDatasources	ds;
    name				model  = this.extensionModel();
    str					destination;

    if (model)
    {
        this.addHtmlEntry("@TFM:OriginModel", model, '', resourceStr(TFMEntityModel));//'<br><p>Originates from extension model ' + model + '</p>';
    }
    if (filterName)
    {
        this.addHtmlEntry("@TFM:Filterheader",filterName, '', resourceStr(TFMEntityFilter));
    }
    if (listId)
    {
        this.addHtmlEntry("@TFM:Listdesign", '"' + listId +'" '+"@TFM:usedtochangeitclick" + '<a href="/?cmp=' + curExt() + '&mi=Action%3A' + menuItemActionStr(TFMPageOverviewSubPageNavigator)+ '&FormName='+ FormStr(TFMPageListDataBinding) + '&pageId=' + this.parmId() +'">'+"@SYS136783"+'</a>',FormStr(TFMPageListDataBinding), resourceStr(TFMEntityLists));
        select count(RecId) from ds where ds.PageID == this.parmId();
        this.addHtmlEntry("@TFM:DataSources", '<a href="/?cmp=' + curExt() + '&mi=Action%3A' + menuItemActionStr(TFMPageOverviewSubPageNavigator)+ '&FormName='+ FormStr(TFMDataSources)+'&pageId='+this.parmId()+'">'+strFmt("@TFM:datasourcesonpage",ds.RecId)+'</a>', FormStr(TFMDataSources), resourceStr(TFMEntityDatasources));
    }

    if(this.getConfiguration() && this.getConfiguration().isOfflineEnabled())
    {
        this.addHtmlEntry("@SYS39786","@TFM:Offlinemodeenabled", '', resourceStr(TFMOfflineManagementIcon));
    }
    else
    {
        this.addHtmlEntry("@SYS39786",'', '', resourceStr(TFMOfflineManagementIcon));
    }

    str overriddenText = '';
    if (TFMDeltaPages::Find(this.parmId()))
    {
        overriddenText = 'Page overridden <br/>' + TFMConstants::lineBreak();
    }
    destination = formStr(TFMPageConfigurator);

    this.addHtmlEntry("@SYS304003", overriddenText + '<a href="/?cmp=' + curExt() + '&mi=Action%3A' + menuItemActionStr(TFMPageOverviewSubPageNavigator)+ '&FormName='+ destination + '&PageId=' + this.parmId() +'">' + "@TFM:Configurepage" + '</a>', destination, resourceStr(TFMEntityCustomizations));
    if (TFMPagesProvider::instance().developerMode() && docHand != null)
    {
        this.addHtmlEntry("@TFM:CodeOrigin", strFmt("@TFM:Declaredintheclass1",classId2Name(classIdGet(docHand))), '',resourceStr(TFMEntityClass));
    }
}

public void addHtmlEntry(str _headline, str _text, str _formName, str _icon)
{
    if(_text)
    {
        tileEntries.insert(_headline,_icon + '|' + _text);
        tileForms.insert(_headline,_formName);
    }
    else
    {
        tileEntries.remove(_headline);
    }

}

    public Name extensionModel()
    {
        int	modelIgnoreID = TFMVersion::modelForClass(className2Id(classStr(TFMDocumentHandler))).Id;        
        Microsoft.Dynamics.AX.Metadata.MetaModel.ModelInfo  modelInfo;
		if (!docHand)
        {
            return '';
        }

		modelInfo = TFMVersion::modelForClass(classIdGet(docHand));
		if (modelInfo.Id == modelIgnoreID)
        {
            return '';
        }
        return modelInfo.DisplayName + ', ' +modelInfo.Publisher;
    }
